import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
gemm_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matmul(torch::Tensor A, torch::Tensor B);
"""
gemm_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#include <cute/tensor.hpp>
using namespace cute;
// C(M,N) = A(M,K) * B(K,N), all row-major float32.
// B is viewed as (N,K) with stride (1,N) so the cute::gemm (M,K)x(N,K)->(M,N)
// "TN" form computes sum_k A(m,k) * B(k,n) exactly.
template <class TA, class TB, class TC>
__global__ static void
gemm_device(int M, int N, int K,
            TA const* __restrict__ A,
            TB const* __restrict__ B,
            TC*       __restrict__ C)
{
  using namespace cute;
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 16;
  constexpr int THREADS = 256;
  // Full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{})); // (M,K) row-major
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, N)); // (N,K) view of B^T
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{})); // (M,N) row-major
  // CTA tiling: 128x128 output tile, 16-wide K slices
  auto cta_tiler = make_shape(Int<BM>{}, Int<BN>{}, Int<BK>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,  X, _1>{}); // (128,16,K/16)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step< X, _1, _1>{}); // (128,16,K/16)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1,  X>{}); // (128,128)
  // Double-buffered shared memory staging buffers
  __shared__ TA smemA[2][BM * BK]; // row-major (BM,K): K-contiguous
  __shared__ alignas(16) TB smemB[2][BK * (BN + 4)]; // padded K-stride to reduce shared-memory bank conflicts
  // Thread layout for compute (256 threads per CTA)
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  // Compute partitions: each thread owns an 8x8 output micro-tile
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{}); // (8,8) (M,N)
  // Register accumulator
  Tensor tCrC = make_tensor<float>(shape(tCgC));
  clear(tCrC);
  const int cta_m = blockIdx.x * BM;
  const int cta_n = blockIdx.y * BN;
  const int K_TILE_MAX = K / BK;
  // Asynchronously stage one 128x16 A tile and one 128x16 B tile.
  // A is vectorized along K; B is vectorized along N (contiguous in B row-major).
  auto load_stage = [&](int k_tile, int stage) {
    const int k0 = k_tile * BK;
    // A: 128x16 floats = 512 float4; 256 threads load 2 float4 each.
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
      const int idx = threadIdx.x + i * THREADS;
      const int row = idx >> 2;  // 4 float4 per row
      const int c4  = idx & 3;
      const float4* src = reinterpret_cast<const float4*>(A + (cta_m + row) * K + k0 + c4 * 4);
      float4* dst = reinterpret_cast<float4*>(smemA[stage] + row * BK + c4 * 4);
      __pipeline_memcpy_async(dst, src, sizeof(float4));
    }
    // B viewed as (N,K): 128x16 floats = 512 float4; 256 threads load 2 float4 each.
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
      const int idx = threadIdx.x + i * THREADS;
      const int n4 = idx & 31; // 32 float4 across N for fixed k
      const int kk = idx >> 5;
      const float4* src = reinterpret_cast<const float4*>(B + (k0 + kk) * N + cta_n + n4 * 4);
      float4* dst = reinterpret_cast<float4*>(smemB[stage] + kk * (BN + 4) + n4 * 4);
      __pipeline_memcpy_async(dst, src, sizeof(float4));
    }
  };
  // Prime the pipeline with the first K tile.
  load_stage(0, 0);
  __pipeline_commit();
  int stage = 0;
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    const int next = k_tile + 1;
    if (next < K_TILE_MAX) {
      load_stage(next, stage ^ 1);
      __pipeline_commit();
      __pipeline_wait_prior(1);
    } else {
      __pipeline_wait_prior(0);
    }
    __syncthreads();
    Tensor sA = make_tensor(make_smem_ptr(smemA[stage]), make_shape(Int<BM>{}, Int<BK>{}), make_stride(Int<BK>{}, Int<1>{}));
    Tensor sB = make_tensor(make_smem_ptr(smemB[stage]), make_shape(Int<BN>{}, Int<BK>{}), make_stride(Int<1>{}, Int<BN + 4>{}));
    Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1,  X>{}); // (8,16) (M,K)
    Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step< X, _1>{}); // (8,16) (N,K)
    gemm(tCsA, tCsB, tCrC); // tCrC += tCsA * tCsB^T
    __syncthreads();
    stage ^= 1;
  }
  // Epilogue: write accumulators to global memory
  axpby(1.0f, tCrC, 0.0f, tCgC);
}
torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0) == K, "Inner dimensions must agree");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 16 == 0,
              "This kernel requires M,N divisible by 128 and K divisible by 16");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());
  float const* ptrA = A_c.data_ptr<float>();
  float const* ptrB = B_c.data_ptr<float>();
  float*       ptrC = C.data_ptr<float>();
  dim3 dimBlock(256);
  dim3 dimGrid((M + 127) / 128, (N + 127) / 128);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_device<float, float, float><<<dimGrid, dimBlock, 0, stream>>>(
      M, N, K, ptrA, ptrB, ptrC);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));
  return C;
}
"""
cute_gemm_ext = load_inline(
    name="cute_square_matmul_ext",
    cpp_sources=gemm_cpp_decl,
    cuda_sources=gemm_cuda_src,
    functions=["matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)
class ModelNew(nn.Module):
    """
    Square matrix multiplication C = A * B implemented with a single
    cooperative tiled CuTe GEMM kernel (128x128 CTA tiles, K-slices of 16,
    double-buffered shared-memory staging with cp.async, per-thread 8x8
    register accumulators).
